// waitForControlEndpoint polls stateDir for the first run's control.json and
// returns the loopback listener address. Run ids are generated by apply, so
// the caller discovers them via the published control endpoint record.
func waitForControlEndpoint(t *testing.T, stateDir string) string {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		addr, _, ok := findRunWithControlEndpoint(t, stateDir)
		if ok {
			return addr
		}
		time.Sleep(20 * time.Millisecond)
	}
	t.Fatalf("control endpoint record under %s not published within 15s", stateDir)
	return ""
}

// findRunWithControlEndpoint scans stateDir's runs dir for a run directory
// publishing its control endpoint; the runs dir also holds flat
// <runID>.json records that must be skipped.
func findRunWithControlEndpoint(t *testing.T, stateDir string) (addr, runID string, found bool) {
	t.Helper()
	entries, err := os.ReadDir(filepath.Join(stateDir, "runs"))
	if err != nil {
		return "", "", false
	}
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		runID := e.Name()
		if addr, err := LocalControlEndpoint(runID); err == nil && addr != "" {
			return addr, runID, true
		}
	}
	return "", "", false
}

// runApplyAsync runs runApply in a goroutine and returns a channel that
// receives its terminal error, so the test can interact with the run's
// control listener while it executes.
func runApplyAsync(opts *applyOptions) <-chan error {
	errCh := make(chan error, 1)
	go func() {
		defer func() {
			if r := recover(); r != nil {
				errCh <- fmt.Errorf("apply panicked: %v", r)
			}
		}()
		errCh <- runApply(context.Background(), *opts)
	}()
	return errCh
}

// resolveApproval delivers a decision over the run's loopback control
// listener (the CRI-255 primary surface).
func resolveApproval(t *testing.T, addr, runID, signal string, payload map[string]string) (accepted bool, reason string) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	resp, err := localControlServiceClientFor(addr).ResolveResume(ctx, &pb.ResumeRequest{
		RunId:   runID,
		Signal:  signal,
		Payload: payload,
	})
	if err != nil {
		t.Fatalf("ResolveResume over %s: %v", addr, err)
	}
	return resp.Accepted, resp.Reason
}

// runEventsFile reads the run's ND-JSON events and returns the ordered
// payload_type values (LocalSink emits PascalCase names).
func runEventsFile(t *testing.T, stateDir, runID string) []string {
	t.Helper()
	f, err := os.Open(filepath.Join(stateDir, "runs", runID, "events.ndjson"))
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		t.Fatalf("read events: %v", err)
	}
	defer f.Close()
	var types []string
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		var env struct {
			PayloadType string `json:"payload_type"`
		}
		if err := json.Unmarshal(sc.Bytes(), &env); err != nil {
			t.Fatalf("decode event line %q: %v", sc.Text(), err)
		}
		types = append(types, env.PayloadType)
	}
	return types
}

// TestApplyLocal_ApprovalResolvedOverLocalControlRPC covers the CRI-255
// acceptance path: a local apply pauses at an approval node with no
// CRITERIA_LOCAL_APPROVAL configured (the once-primary file/env path is
// unused) and the run finishes only after a decision arrives over the run's
// loopback control listener.
func TestApplyLocal_ApprovalResolvedOverLocalControlRPC(t *testing.T) {
	adapterDir := filepath.Dir(buildNoopAdapterBinary(t))
	stateDir := t.TempDir()
	t.Setenv("CRITERIA_ADAPTERS", adapterDir)
	t.Setenv("CRITERIA_STATE_DIR", stateDir)
	t.Setenv("CRITERIA_LOCAL_APPROVAL", "")

	errCh := runApplyAsync(&applyOptions{workflowPath: filepath.Join("testdata", "local_approval_simple"), tty: func() bool { return false }})

	addr := waitForControlEndpoint(t, stateDir)
	runID := singleRunID(t, stateDir)

	// An unresolved pause means the run waits; check pause is observable via
	// the control surface before the decision. Then deliver approved.
	accepted, reason := resolveApproval(t, addr, runID, "review", map[string]string{"decision": "approved"})
	if !accepted || reason != "ok" {
		t.Fatalf("ResolveResume = (accepted=%t, reason=%q), want accepted ok", accepted, reason)
	}

	select {
	case err := <-errCh:
		if err != nil {
			t.Fatalf("expected successful run after RPC approval, got: %v", err)
		}
	case <-time.After(30 * time.Second):
		t.Fatal("runApply did not return after RPC approval")
	}

	// Same event vocabulary as castle runs: an approval pause keeps the
	// richer ApprovalRequested event; resume rides RunResumed.
	evts := runEventsFile(t, stateDir, runID)
	for _, want := range []string{"ApprovalRequested", "RunResumed"} {
		if !containsString(evts, want) {
			t.Errorf("events missing %s; got %v", want, evts)
		}
	}
	// The control record is a startup artifact: it must be gone at teardown.
	if _, sErr := os.Stat(filepath.Join(stateDir, "runs", runID, "control.json")); !os.IsNotExist(sErr) {
		t.Errorf("control.json still present after run end: %v", sErr)
	}
}

// TestApplyLocal_ApprovalRejectedOverLocalControlRPC delivers a rejected
// decision over the RPC surface: the run resolves to the rejected terminal
// state and apply reports a failed run.
func TestApplyLocal_ApprovalRejectedOverLocalControlRPC(t *testing.T) {
	adapterDir := filepath.Dir(buildNoopAdapterBinary(t))
	stateDir := t.TempDir()
	t.Setenv("CRITERIA_ADAPTERS", adapterDir)
	t.Setenv("CRITERIA_STATE_DIR", stateDir)
	t.Setenv("CRITERIA_LOCAL_APPROVAL", "")

	errCh := runApplyAsync(&applyOptions{workflowPath: filepath.Join("testdata", "local_approval_simple"), tty: func() bool { return false }})

	addr := waitForControlEndpoint(t, stateDir)
	runID := singleRunID(t, stateDir)

	accepted, reason := resolveApproval(t, addr, runID, "review", map[string]string{"decision": "rejected"})
	if !accepted || reason != "ok" {
		t.Fatalf("ResolveResume = (accepted=%t, reason=%q), want accepted ok", accepted, reason)
	}

	select {
	case err := <-errCh:
		if err == nil {
			t.Fatal("rejected approval: expected non-nil error for terminal failed run")
		}
		if !strings.Contains(err.Error(), "success=false") {
			t.Fatalf("error should report success=false, got: %v", err)
		}
	case <-time.After(30 * time.Second):
		t.Fatal("runApply did not return after RPC rejection")
	}
}

