// TestApplyLocal_UnknownSignalRejectedByRPC exercises the ResolveResume
// rejection reasons while a run is genuinely paused: the pause must be intact
// and the run still completable afterwards (no state corruption from bad
// delivery attempts).
func TestApplyLocal_UnknownSignalRejectedByRPC(t *testing.T) {
	adapterDir := filepath.Dir(buildNoopAdapterBinary(t))
	stateDir := t.TempDir()
	t.Setenv("CRITERIA_ADAPTERS", adapterDir)
	t.Setenv("CRITERIA_STATE_DIR", stateDir)
	t.Setenv("CRITERIA_LOCAL_APPROVAL", "")

	errCh := runApplyAsync(&applyOptions{workflowPath: filepath.Join("testdata", "local_approval_simple"), tty: func() bool { return false }})

	addr := waitForControlEndpoint(t, stateDir)
	runID := singleRunID(t, stateDir)

	// An unknown signal name maps to no pending pause.
	if accepted, reason := resolveApproval(t, addr, runID, "nonexistent", nil); accepted || reason != "no_pending_signal" {
		t.Fatalf("unknown signal = (accepted=%t, reason=%q), want no_pending_signal", accepted, reason)
	}
	// A payload missing its decision for the mapped pause is refused without
	// consuming the pause.
	if accepted, reason := resolveApproval(t, addr, runID, "review", nil); accepted || reason != "signal_mismatch" {
		t.Fatalf("empty decision payload = (accepted=%t, reason=%q), want signal_mismatch", accepted, reason)
	}
	if accepted, reason := resolveApproval(t, addr, runID, "review", map[string]string{"decision": "bogus"}); accepted || reason != "signal_mismatch" {
		t.Fatalf("invalid decision = (accepted=%t, reason=%q), want signal_mismatch", accepted, reason)
	}

	// The pause survived; the correct decision resolves it.
	if accepted, reason := resolveApproval(t, addr, runID, "review", map[string]string{"decision": "approved"}); !accepted || reason != "ok" {
		t.Fatalf("ResolveResume after rejections = (accepted=%t, reason=%q), want accepted", accepted, reason)
	}
	select {
	case err := <-errCh:
		if err != nil {
			t.Fatalf("expected successful run after retries, got: %v", err)
		}
	case <-time.After(30 * time.Second):
		t.Fatal("runApply did not return after RPC approval")
	}
}

// TestApplyLocal_BoundaryPauseResumeOverLocalControlRPC covers the CRI-255
// boundary pause: PauseRun while a step runs, the run parks at the next
// checkpoint boundary (RunPaused with mode external), and ResumeRun (no
// payload) continues to completion.
func TestApplyLocal_BoundaryPauseResumeOverLocalControlRPC(t *testing.T) {
	adapterDir := filepath.Dir(buildNoopAdapterBinary(t))
	stateDir := t.TempDir()
	t.Setenv("CRITERIA_ADAPTERS", adapterDir)
	t.Setenv("CRITERIA_STATE_DIR", stateDir)
	t.Setenv("CRITERIA_LOCAL_APPROVAL", "")

	errCh := runApplyAsync(&applyOptions{workflowPath: filepath.Join("testdata", "local_control_pause")})

	addr := waitForControlEndpoint(t, stateDir)
	runID := singleRunID(t, stateDir)

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	client := localControlServiceClientFor(addr)
	if _, err := client.PauseRun(ctx, &pb.PauseRunRequest{RunId: runID}); err != nil {
		t.Fatalf("PauseRun: %v", err)
	}

	if _, err := client.ResumeRun(ctx, &pb.ResumeRunRequest{RunId: runID}); err != nil {
		t.Fatalf("ResumeRun: %v", err)
	}

	select {
	case err := <-errCh:
		if err != nil {
			t.Fatalf("expected successful run after resume, got: %v", err)
		}
	case <-time.After(30 * time.Second):
		t.Fatal("runApply did not return after ResumeRun")
	}

	// The boundary pause carries the shared vocabulary: mode "external" only.
	var sawPausedExternal, sawResumed bool
	for _, line := range eventLines(t, stateDir, runID) {
		var env struct {
			PayloadType string `json:"payload_type"`
			Payload     struct {
				Mode string `json:"mode"`
			} `json:"payload"`
		}
		if err := json.Unmarshal([]byte(line), &env); err != nil {
			t.Fatalf("decode event: %v", err)
		}
		switch {
		case env.PayloadType == "RunPaused" && env.Payload.Mode == "external":
			sawPausedExternal = true
		case env.PayloadType == "RunResumed":
			sawResumed = true
		}
	}
	if !sawPausedExternal {
		t.Error("events missing RunPaused with mode external")
	}
	if !sawResumed {
		t.Error("events missing RunResumed")
	}
}

// TestPauseResumeCLIVerbsTargetLocalRun pins the CLI verb wiring (CRI-255
// acceptance: pause/resume verbs work against a local run with no castle
// running): both verbs execute as plain cobra commands with no --server flag
// and no CRITERIA_SERVER_URL, discover the run's control listener from
// control.json, and land their effect — the run pauses, then resumes to
// completion with the shared RunPaused/RunResumed event vocabulary.
func TestPauseResumeCLIVerbsTargetLocalRun(t *testing.T) {
	adapterDir := filepath.Dir(buildNoopAdapterBinary(t))
	stateDir := t.TempDir()
	t.Setenv("CRITERIA_ADAPTERS", adapterDir)
	t.Setenv("CRITERIA_STATE_DIR", stateDir)
	t.Setenv("CRITERIA_LOCAL_APPROVAL", "")
	t.Setenv("CRITERIA_SERVER_URL", "")
	t.Setenv("CRITERIA_CONTROL_ADDR", "")

	errCh := runApplyAsync(&applyOptions{workflowPath: filepath.Join("testdata", "local_control_pause")})

	waitForControlEndpoint(t, stateDir)
	runID := singleRunID(t, stateDir)

	pauseCmd := NewPauseCmd()
	pauseCmd.SetArgs([]string{"--run-id", runID})
	if err := pauseCmd.Execute(); err != nil {
		t.Fatalf("pause verb against local run: %v", err)
	}

	// The pause verb blocks until the pause lands with durable state; the
	// parked run must carry the same vocabulary the castle path emits.
	if !waitForPayloadType(t, stateDir, runID, "RunPaused") {
		t.Error("events missing RunPaused after the pause verb")
	}

	resumeCmd := NewResumeCmd()
	resumeCmd.SetArgs([]string{"--run-id", runID})
	if err := resumeCmd.Execute(); err != nil {
		t.Fatalf("resume verb against local run: %v", err)
	}

	select {
	case err := <-errCh:
		if err != nil {
			t.Fatalf("expected successful run after the resume verb, got: %v", err)
		}
	case <-time.After(30 * time.Second):
		t.Fatal("runApply did not return after the resume verb")
	}
	if !containsString(runEventsFile(t, stateDir, runID), "RunResumed") {
		t.Error("events missing RunResumed after the resume verb")
	}
}

// waitForPayloadType polls the run's event stream for a payload type,
// tolerating the async drain between the control RPC and the run-state
// view.
func waitForPayloadType(t *testing.T, stateDir, runID, payloadType string) bool {
	t.Helper()
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		if containsString(runEventsFile(t, stateDir, runID), payloadType) {
			return true
		}
		time.Sleep(40 * time.Millisecond)
	}
	return false
}

