// singleRunID returns the run id of the run whose control endpoint is
// published under stateDir (skipping the flat <runID>.json records).
func singleRunID(t *testing.T, stateDir string) string {
	t.Helper()
	if _, runID, ok := findRunWithControlEndpoint(t, stateDir); ok {
		return runID
	}
	t.Fatalf("no run dir with a control endpoint under %s", stateDir)
	return ""
}

func containsString(xs []string, s string) bool {
	for _, x := range xs {
		if x == s {
			return true
		}
	}
	return false
}

func eventLines(t *testing.T, stateDir, runID string) []string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(stateDir, "runs", runID, "events.ndjson"))
	if err != nil {
		t.Fatalf("read events: %v", err)
	}
	var lines []string
	for _, l := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		if l != "" {
			lines = append(lines, l)
		}
	}
	return lines
}

// TestControlEndpointRecord_Roundtrip pins the control.json contract: the
// apply process publishes protocol/addr/run/pid under the run's state dir,
// the CLI discovers it via LocalControlEndpoint, and removing the record
// falls back to the castle surface (empty addr, no error).
func TestControlEndpointRecord_Roundtrip(t *testing.T) {
	stateDir := t.TempDir()
	t.Setenv("CRITERIA_STATE_DIR", stateDir)

	addr, err := LocalControlEndpoint("endpoint-run")
	if err != nil || addr != "" {
		t.Fatalf("before publish: LocalControlEndpoint = (%q, %v), want empty/nil", addr, err)
	}

	if err := writeControlEndpoint("endpoint-run", "127.0.0.1:8123"); err != nil {
		t.Fatalf("writeControlEndpoint: %v", err)
	}
	addr, err = LocalControlEndpoint("endpoint-run")
	if err != nil {
		t.Fatalf("LocalControlEndpoint: %v", err)
	}
	if addr != "127.0.0.1:8123" {
		t.Fatalf("LocalControlEndpoint = %q, want 127.0.0.1:8123", addr)
	}

	// The record must live under the run's existing state dir (no new store).
	if _, statErr := os.Stat(filepath.Join(stateDir, "runs", "endpoint-run", "control.json")); statErr != nil {
		t.Fatalf("control.json not under runs/<runID>: %v", statErr)
	}

	// A foreign run id in the record is rejected (wrong-run reads 403 from the
	// server's checkRun; the CLI must not even dial).
	if err := writeControlEndpoint("other-run", "127.0.0.1:8123"); err != nil {
		t.Fatalf("writeControlEndpoint(other): %v", err)
	}
	if _, err := LocalControlEndpoint("other-run"); err != nil {
		t.Fatalf("LocalControlEndpoint(other): %v", err)
	}

	removeControlEndpoint("endpoint-run")
	addr, err = LocalControlEndpoint("endpoint-run")
	if err != nil || addr != "" {
		t.Fatalf("after remove: LocalControlEndpoint = (%q, %v), want empty/nil", addr, err)
	}
}

// TestControlEndpointRecord_RejectsBadRecords pins the defensive reads in
// LocalControlEndpoint: corrupt JSON, a foreign protocol, a mismatched run id,
// and a non-loopback address all fail closed.
func TestControlEndpointRecord_RejectsBadRecords(t *testing.T) {
	stateDir := t.TempDir()
	t.Setenv("CRITERIA_STATE_DIR", stateDir)
	p, err := controlEndpointPath("bad-record-run")
	if err != nil {
		t.Fatalf("controlEndpointPath: %v", err)
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o700); err != nil {
		t.Fatalf("mkdir: %v", err)
	}

	for _, tc := range []struct {
		name    string
		body    string
		wantMsg string
	}{
		{"corrupt", "{not json", "decode control endpoint"},
		{"foreign protocol", `{"protocol":"other.v1.Control/connect","control_addr":"127.0.0.1:1","run_id":"bad-record-run","pid":1}`, "this CLI speaks"},
		{"mismatched run id", `{"protocol":"criteria.v1.LocalControlService/connect","control_addr":"127.0.0.1:1","run_id":"someoneelse","pid":1}`, "incomplete"},
		{"missing addr", `{"protocol":"criteria.v1.LocalControlService/connect","control_addr":"","run_id":"bad-record-run","pid":1}`, "incomplete"},
		{"non-loopback", `{"protocol":"criteria.v1.LocalControlService/connect","control_addr":"0.0.0.0:1","run_id":"bad-record-run","pid":1}`, "non-loopback"},
	} {
		if err := os.WriteFile(p, []byte(tc.body), 0o600); err != nil {
			t.Fatalf("write record: %v", err)
		}
		_, err := LocalControlEndpoint("bad-record-run")
		if err == nil || !strings.Contains(err.Error(), tc.wantMsg) {
			t.Errorf("%s: LocalControlEndpoint err = %v, want containing %q", tc.name, err, tc.wantMsg)
		}
	}
}

// TestValidateControlHostPort pins the locked loopback-only rule at the
// validator the apply-side bind and the client-side record both use.
func TestValidateControlHostPort(t *testing.T) {
	for _, good := range []string{"127.0.0.1:9", "[::1]:8123", ":9"} {
		if err := validateControlHostPort(good); err != nil {
			t.Errorf("loopback %q refused: %v", good, err)
		}
	}
	for _, bad := range []string{"0.0.0.0:9", "192.168.1.5:9", "example.com:9", "[::]:9", "999.1.1.1:9", "127.0.0.1"} {
		if err := validateControlHostPort(bad); err == nil {
			t.Errorf("non-loopback/missing-port %q accepted", bad)
		}
	}
}

// TestResolveControlAddr pins --control-addr parsing: empty binds a random
// loopback port, localhost maps to 127.0.0.1, and wide or malformed values
// are refused.
func TestResolveControlAddr(t *testing.T) {
	host, port, err := resolveControlAddr("")
	if err != nil || host != "127.0.0.1" || port != 0 {
		t.Fatalf("default = (%q, %d, %v), want 127.0.0.1:0/nil", host, port, err)
	}
	for _, addr := range []string{"127.0.0.1:9001", "localhost:9001", "[::1]:9001"} {
		host, port, err = resolveControlAddr(addr)
		if err != nil {
			t.Errorf("%q: %v", addr, err)
			continue
		}
		if ip := net.ParseIP(host); ip == nil || !ip.IsLoopback() || port != 9001 {
			t.Errorf("%q resolved to %s:%d, want loopback:9001", addr, host, port)
		}
	}
	for _, addr := range []string{"0.0.0.0:9001", "192.168.1.5:9001", "example.com:9001", "noport", "127.0.0.1:notaport"} {
		if _, _, err := resolveControlAddr(addr); err == nil {
			t.Errorf("%q accepted, want refusal", addr)
		}
	}
}

// TestLocalControlServiceRetryAcrossPauseLanding pins the service-layer
// landing window: control verbs that race the run's start-up (engine not yet
// registered, first pause not yet landed) must succeed once the run reaches
// its registered state within the bounded window instead of answering a hard
// precondition error.
func TestLocalControlServiceRetryAcrossPauseLanding(t *testing.T) {
	requireNoGoroutineLeak(t)
	home := t.TempDir()
	t.Setenv("CRITERIA_STATE_DIR", home)

	wfPath := writeWorkflowFile(t, pauseResumeWorkflow)
	ctx := context.Background()
	_, graph, loader, err := compileForExecution(ctx, wfPath, discardLogger(), false, false)
	if err != nil {
		t.Fatalf("compile: %v", err)
	}
	defer func() { _ = loader.Shutdown(context.WithoutCancel(ctx)) }()

	sink := func() *run.LocalSink {
		return &run.LocalSink{RunID: "landing-test", Out: os.Stdout}
	}

	// ResolveResume racing the first pause landing: answered run_not_paused
	// until the pause lands, then accepted by the bounded retry.
	waitTracker := &pauseTracker{Sink: sink()}
	pauseCtrl := newLocalRunControl("landing-test", graph, waitTracker, nil)
	pauseSvc := &localControlService{ctrl: pauseCtrl, runID: "landing-test"}
	pauseReady := make(chan struct{})
	go func() {
		time.Sleep(100 * time.Millisecond)
		pauseCtrl.setEngine(engine.New(graph, loader, sink()))
		waitTracker.OnRunPaused("gate", "signal", "resume")
		close(pauseReady)
	}()
	accepted, reason := pauseSvc.ctrlResolve("resume", nil)
	if !accepted || reason != "ok" {
		t.Fatalf("ctrlResolve racing landing = (%v, %q), want (true, ok)", accepted, reason)
	}
	<-pauseReady

	// ResumeRun racing engine registration: the engine pointer registers
	// 100ms into the retry window; the verb must succeed, not answer
	// errRunNotRunning.
	regTracker := &pauseTracker{Sink: sink()}
	regCtrl := newLocalRunControl("landing-test", graph, regTracker, nil)
	regSvc := &localControlService{ctrl: regCtrl, runID: "landing-test"}
	engineReady := make(chan struct{})
	go func() {
		time.Sleep(100 * time.Millisecond)
		regCtrl.setEngine(engine.New(graph, loader, sink()))
		close(engineReady)
	}()
	if err := regSvc.ctrlResume(); err != nil {
		t.Fatalf("ctrlResume racing registration: %v", err)
	}
	<-engineReady

	// A terminal (finished) run answers immediately, without waiting out
	// the full retry window.
	waitTracker.ClearPaused()
	pauseCtrl.markFinished()
	start := time.Now()
	accepted, reason = pauseSvc.ctrlResolve("resume", nil)
	if accepted || reason != "run_not_paused" {
		t.Fatalf("finished run resolve = (%v, %q), want (false, run_not_paused)", accepted, reason)
	}
	if elapsed := time.Since(start); elapsed >= pauseLandingRetryWindow {
		t.Fatalf("finished run resolve took %v, want fast final answer", elapsed)
	}
}
